import React, { Suspense, useRef } from "react";
import { Canvas, useLoader } from "@react-three/fiber";
import { Environment, OrbitControls, useGLTF } from "@react-three/drei";
import { RGBELoader } from "three/examples/jsm/loaders/RGBELoader";
import "./App.css";
// 加载 HDR 环境贴图
const useHDRTexture = (url: string) => {
  return useLoader(RGBELoader, url);
};
// 异步加载 GLTF 模型
const Model = () => {
  const { scene, nodes, materials } = useGLTF(
    "./model.gltf"
    // "https://file.cdn.sunmi.com/newebsite/cms/sunmi-home/models/model-draco-processed.gltf"
  );
  // 调试输出材质信息
  console.log("模型材质信息:", materials);

  // 调整模型大小
  scene.scale.set(0.002, 0.002, 0.002); // 减小模型比例
  return <primitive object={scene} scale={0.002} />;
};

function App() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const hdrTexture = "/environment.hdr";
  return (
    <div className="app-container">
      <h1 className="title">Three.js GLTF 模型查看器</h1>
      <Canvas
        camera={{ position: [0, 1, 5] }}
        ref={canvasRef}
        className="canvas-container"
      >
        {/* 使用 HDR 环境贴图 */}
        <Environment background files={hdrTexture} />
        <ambientLight intensity={0.5} />
        <directionalLight position={[10, 10, 5]} intensity={1} />
        <directionalLight position={[-10, -10, -5]} intensity={0.5} />

        <Suspense fallback={<mesh />}>
          <Model />
        </Suspense>

        {/* 添加轨道控制器，允许用户旋转和缩放模型 */}
        <OrbitControls />
      </Canvas>
      <div className="instructions">
        <p>使用鼠标左键拖动旋转模型，右键拖动平移，滚轮缩放</p>
      </div>
    </div>
  );
}

export default App;
